#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define SAMTOOLS_VERSION "be7a51c"
#define HTSLIB_VERSION "1.23.1"

typedef struct {
    int value;
    const char *name;
    const char *description;
} Flag;

static Flag flags[] = {
    {0x1, "PAIRED", "paired-end / multiple-segment sequencing technology"},
    {0x2, "PROPER_PAIR", "each segment properly aligned according to aligner"},
    {0x4, "UNMAP", "segment unmapped"},
    {0x8, "MUNMAP", "next segment in the template unmapped"},
    {0x10, "REVERSE", "SEQ is reverse complemented"},
    {0x20, "MREVERSE", "SEQ of next segment in template is rev.complemented"},
    {0x40, "READ1", "the first segment in the template"},
    {0x80, "READ2", "the last segment in the template"},
    {0x100, "SECONDARY", "secondary alignment"},
    {0x200, "QCFAIL", "not passing quality controls or other filters"},
    {0x400, "DUP", "PCR or optical duplicate"},
    {0x800, "SUPPLEMENTARY", "supplementary alignment"},
    {0, NULL, NULL}
};

void print_help() {
    fprintf(stdout, "\nProgram: samtools (Tools for alignments in the SAM format)\n");
    fprintf(stdout, "Version: %s (using htslib %s)\n\n", SAMTOOLS_VERSION, HTSLIB_VERSION);
    fprintf(stdout, "Usage:   samtools <command> [options]\n\n");
    fprintf(stdout, "Commands:\n");
    fprintf(stdout, "  -- Indexing\n");
    fprintf(stdout, "     dict           create a sequence dictionary file\n");
    fprintf(stdout, "     faidx          index/extract FASTA\n");
    fprintf(stdout, "     fqidx          index/extract FASTQ\n");
    fprintf(stdout, "     index          index alignment\n\n");
    fprintf(stdout, "  -- Editing\n");
    fprintf(stdout, "     calmd          recalculate MD/NM tags and '=' bases\n");
    fprintf(stdout, "     fixmate        fix mate information\n");
    fprintf(stdout, "     reheader       replace BAM header\n");
    fprintf(stdout, "     targetcut      cut fosmid regions (for fosmid pool only)\n");
    fprintf(stdout, "     addreplacerg   adds or replaces RG tags\n");
    fprintf(stdout, "     markdup        mark duplicates\n");
    fprintf(stdout, "     ampliconclip   clip oligos from the end of reads\n\n");
    fprintf(stdout, "  -- File operations\n");
    fprintf(stdout, "     collate        shuffle and group alignments by name\n");
    fprintf(stdout, "     cat            concatenate BAMs\n");
    fprintf(stdout, "     consensus      produce a consensus Pileup/FASTA/FASTQ\n");
    fprintf(stdout, "     merge          merge sorted alignments\n");
    fprintf(stdout, "     mpileup        multi-way pileup\n");
    fprintf(stdout, "     sort           sort alignment file\n");
    fprintf(stdout, "     split          splits a file by read group\n");
    fprintf(stdout, "     quickcheck     quickly check if SAM/BAM/CRAM file appears intact\n");
    fprintf(stdout, "     fastq          converts a BAM to a FASTQ\n");
    fprintf(stdout, "     fasta          converts a BAM to a FASTA\n");
    fprintf(stdout, "     import         Converts FASTA or FASTQ files to SAM/BAM/CRAM\n");
    fprintf(stdout, "     reference      Generates a reference from aligned data\n");
    fprintf(stdout, "     reset          Reverts aligner changes in reads\n\n");
    fprintf(stdout, "  -- Statistics\n");
    fprintf(stdout, "     bedcov         read depth per BED region\n");
    fprintf(stdout, "     coverage       alignment depth and percent coverage\n");
    fprintf(stdout, "     depth          compute the depth\n");
    fprintf(stdout, "     flagstat       simple stats\n");
    fprintf(stdout, "     idxstats       BAM index stats\n");
    fprintf(stdout, "     cram-size      list CRAM Content-ID and Data-Series sizes\n");
    fprintf(stdout, "     phase          phase heterozygotes\n");
    fprintf(stdout, "     stats          generate stats (former bamcheck)\n");
    fprintf(stdout, "     ampliconstats  generate amplicon specific stats\n");
    fprintf(stdout, "     checksum       produce order-agnostic checksums of sequence content\n\n");
    fprintf(stdout, "  -- Viewing\n");
    fprintf(stdout, "     flags          explain BAM flags\n");
    fprintf(stdout, "     head           header viewer\n");
    fprintf(stdout, "     tview          text alignment viewer\n");
    fprintf(stdout, "     view           SAM<->BAM<->CRAM conversion\n");
    fprintf(stdout, "     depad          convert padded BAM to unpadded BAM\n");
    fprintf(stdout, "     samples        list the samples in a set of SAM/BAM/CRAM files\n\n");
    fprintf(stdout, "  -- Misc\n");
    fprintf(stdout, "     help [cmd]     display this help message or help for [cmd]\n");
    fprintf(stdout, "     version        detailed version information\n\n");
}

void print_version() {
    fprintf(stdout, "samtools %s\n", SAMTOOLS_VERSION);
    fprintf(stdout, "Using htslib %s\n", HTSLIB_VERSION);
    fprintf(stdout, "Copyright (C) 2025 Genome Research Ltd.\n\n");
    fprintf(stdout, "Samtools compilation details:\n");
    fprintf(stdout, "    Features:       build=configure curses=yes \n");
    fprintf(stdout, "    CC:             gcc\n");
    fprintf(stdout, "    CPPFLAGS:       \n");
    fprintf(stdout, "    CFLAGS:         -Wall -g -O2\n");
    fprintf(stdout, "    LDFLAGS:        \n");
    fprintf(stdout, "    HTSDIR:         htslib\n");
    fprintf(stdout, "    LIBS:           \n");
    fprintf(stdout, "    CURSES_LIB:     -lncursesw\n\n");
    fprintf(stdout, "HTSlib compilation details:\n");
    fprintf(stdout, "    Features:       build=Makefile libcurl=yes S3=no GCS=no libdeflate=no lzma=yes bzip2=yes plugins=no htscodecs=1.6.6\n");
    fprintf(stdout, "    CC:             gcc\n");
    fprintf(stdout, "    CPPFLAGS:       \n");
    fprintf(stdout, "    CFLAGS:         -g -Wall -O2 -fvisibility=hidden\n");
    fprintf(stdout, "    LDFLAGS:        -fvisibility=hidden\n\n");
    fprintf(stdout, "HTSlib URL scheme handlers present:\n");
    fprintf(stdout, "    built-in:\t file, preload, data\n");
    fprintf(stdout, "    libcurl:\t gophers, smtp, ldaps, smb, rtsp, tftp, pop3, smbs, imaps, pop3s, ftps, https, http, ftp, gopher, imap, sftp, ldap, smtps, scp, dict, mqtt, telnet, rtmp\n");
    fprintf(stdout, "    crypt4gh-needed:\t crypt4gh\n");
    fprintf(stdout, "    mem:\t mem\n");
}

void print_flags_help() {
    fprintf(stdout, "About: Convert between textual and numeric flag representation\n");
    fprintf(stdout, "Usage: samtools flags FLAGS...\n\n");
    fprintf(stdout, "Each FLAGS argument is either an INT (in decimal/hexadecimal/octal) representing\n");
    fprintf(stdout, "a combination of the following numeric flag values, or a comma-separated string\n");
    fprintf(stdout, "NAME,...,NAME representing a combination of the following flag names:\n\n");
    for (int i = 0; flags[i].name != NULL; i++) {
        fprintf(stdout, "   0x%-2x  %3d  %-12s %s\n",
                flags[i].value, flags[i].value, flags[i].name, flags[i].description);
    }
}

void print_faidx_help() {
    fprintf(stdout, "Usage: samtools faidx <file.fa|file.fa.gz> [<reg> [...]]\n");
    fprintf(stdout, "Option: \n");
    fprintf(stdout, "  -o, --output FILE        Write FASTA to file.\n");
    fprintf(stdout, "  -n, --length INT         Length of FASTA sequence line. [60]\n");
    fprintf(stdout, "  -c, --continue           Continue after trying to retrieve missing region.\n");
    fprintf(stdout, "  -r, --region-file FILE   File of regions.  Format is chr:from-to. One per line.\n");
    fprintf(stdout, "  -i, --reverse-complement Reverse complement sequences.\n");
    fprintf(stdout, "      --mark-strand TYPE   Add strand indicator to sequence name\n");
    fprintf(stdout, "                           TYPE = rc   for /rc on negative strand (default)\n");
    fprintf(stdout, "                                  no   for no strand indicator\n");
    fprintf(stdout, "                                  sign for (+) / (-)\n");
    fprintf(stdout, "                                  custom,<pos>,<neg> for custom indicator\n");
    fprintf(stdout, "      --fai-idx      FILE  name of the index file (default file.fa.fai).\n");
    fprintf(stdout, "      --gzi-idx      FILE  name of compressed file index (default file.fa.gz.gzi).\n");
    fprintf(stdout, "  -f, --fastq              File and index in FASTQ format.\n");
    fprintf(stdout, "  -h, --help               This message.\n");
    fprintf(stdout, "      --output-fmt-option OPT[=VAL]\n");
    fprintf(stdout, "               Specify a single output file format option in the form\n");
    fprintf(stdout, "               of OPTION or OPTION=VALUE\n");
    fprintf(stdout, "  -@, --threads INT\n");
    fprintf(stdout, "               Number of additional threads to use [0]\n");
    fprintf(stdout, "      --write-index\n");
    fprintf(stdout, "               Automatically index the output files [off]\n\n");
    fprintf(stdout, "See https://www.htslib.org/doc/samtools.html#GLOBAL_COMMAND_OPTIONS\n");
    fprintf(stdout, "for more details.\n");
}

void handle_flags(int argc, char *argv[]) {
    if (argc <= 2) {
        print_flags_help();
        return;
    }

    // Parse flag arguments
    int result = 0;
    int is_numeric = 0;

    for (int i = 2; i < argc; i++) {
        char *arg = argv[i];
        char *endptr;

        // Try to parse as number (decimal, hex, or octal)
        long val = strtol(arg, &endptr, 0);
        if (*endptr == '\0') {
            result = val;
            is_numeric = 1;
        } else {
            // Parse as comma-separated names
            char arg_copy[256];
            strncpy(arg_copy, arg, sizeof(arg_copy) - 1);
            arg_copy[sizeof(arg_copy) - 1] = '\0';

            char *token = strtok(arg_copy, ",");
            while (token != NULL) {
                for (int j = 0; flags[j].name != NULL; j++) {
                    if (strcmp(flags[j].name, token) == 0) {
                        result |= flags[j].value;
                        break;
                    }
                }
                token = strtok(NULL, ",");
            }
        }
    }

    // Output the flags
    // Find all flags that are set
    char flag_names[512] = "";
    int first = 1;

    for (int i = 0; flags[i].name != NULL; i++) {
        if ((result & flags[i].value) == flags[i].value) {
            if (!first) strcat(flag_names, ",");
            strcat(flag_names, flags[i].name);
            first = 0;
        }
    }

    fprintf(stdout, "0x%-x\t%d\t%s\n", result, result, flag_names);
}

int main(int argc, char *argv[]) {
    if (argc == 1) {
        print_help();
        return 1;
    }

    if (strcmp(argv[1], "--help") == 0 || strcmp(argv[1], "-h") == 0) {
        print_help();
        return 0;
    }

    if (strcmp(argv[1], "help") == 0) {
        if (argc > 2) {
            if (strcmp(argv[2], "version") == 0) {
                print_version();
                return 0;
            } else if (strcmp(argv[2], "flags") == 0) {
                print_flags_help();
                return 0;
            } else if (strcmp(argv[2], "faidx") == 0) {
                print_faidx_help();
                return 0;
            }
        }
        print_help();
        return 0;
    }

    if (strcmp(argv[1], "version") == 0) {
        print_version();
        return 0;
    }

    if (strcmp(argv[1], "flags") == 0) {
        handle_flags(argc, argv);
        return 0;
    }

    if (strcmp(argv[1], "faidx") == 0) {
        if (argc > 2 && (strcmp(argv[2], "-h") == 0 || strcmp(argv[2], "--help") == 0)) {
            print_faidx_help();
            return 0;
        }
        // For now, just show help
        print_faidx_help();
        return 1;
    }

    // Unrecognized command
    print_help();
    return 1;
}
