void handle_flags(int argc, char *argv[]) {
    if (argc <= 2) {
        print_flags_help();
        return;
    }

    // Parse flag arguments
    int result = 0;

    for (int i = 2; i < argc; i++) {
        char *arg = argv[i];
        char *endptr;

        // Try to parse as number (decimal, hex, or octal)
        long val = strtol(arg, &endptr, 0);
        if (*endptr == '\0') {
            result = val;
        } else {
            // Parse as comma-separated names
            char arg_copy[256];
            strncpy(arg_copy, arg, sizeof(arg_copy) - 1);
            arg_copy[sizeof(arg_copy) - 1] = '\0';

            char *token = strtok(arg_copy, ",");
            while (token != NULL) {
                for (int j = 0; flags[j].name != NULL; j++) {
                    if (strcmp(flags[j].name, token) == 0) {
                        result |= flags[j].value;
                        break;
                    }
                }
                token = strtok(NULL, ",");
            }
        }
    }

    // Output the flags
    // Find all flags that are set
    char flag_names[512] = "";
    int first = 1;

    for (int i = 0; flags[i].name != NULL; i++) {
        if ((result & flags[i].value) == flags[i].value) {
            if (!first) strcat(flag_names, ",");
            strcat(flag_names, flags[i].name);
            first = 0;
        }
    }

    fprintf(stdout, "0x%-x\t%d\t%s\n", result, result, flag_names);
}

int main(int argc, char *argv[]) {
    if (argc == 1) {
        print_help();
        return 1;
    }

    if (strcmp(argv[1], "--help") == 0 || strcmp(argv[1], "-h") == 0) {
        print_help();
        return 0;
